mapper.select:
select * from mes_change_point_handle
WHERE 1 = 1

    AND config_code = #{query.configCode}


    AND config_content LIKE CONCAT('%', #{query.configContent}, '%')


    AND category = #{query.category}


    AND status = #{query.status}


    AND loss_category = #{query.lossCategory}


    AND loss_category IS NULL


    AND trigger_time >= #{query.queryStartTime}


    AND trigger_time < #{query.queryEndTime}


    AND affected_wip_qty IS NOT NULL


    AND task_code = #{query.taskCode}


    AND route_code = #{query.routeCode}


    AND transfer_code = #{query.transferCode}


    AND factory_code = #{query.factoryCode}

order by create_time desc
